-- State transitions declared for UnbuildOrder: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION manufacturing.unbuild_orders_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'done'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: unbuild_orders.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_unbuild_orders__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS unbuild_orders_status_transition_check ON manufacturing.unbuild_orders;
CREATE TRIGGER unbuild_orders_status_transition_check
    BEFORE UPDATE OF "status" ON manufacturing.unbuild_orders
    FOR EACH ROW EXECUTE FUNCTION manufacturing.unbuild_orders_status_transition_check();
